-- A cited explanation per official cClassTrib (ADR 0022): why the classification has its treatment, generated by
-- pipelines/rtc/rtc04_explain.py from the LC 214 provisions the bridge links to it (ai.rtc_lc214_fundamento, ADR 0021)
-- and the facts of the Receita's table, by the local LLM, behind the barriers of the LC 214 generator (ADR 0015).
--
-- Grain: one row per classification (silver.rtc_cclasstrib.cltr_id: code x tax group x start of validity).
-- Incremental: a row is regenerated only when its fingerprint (prompt with context and facts, prompt version, model
-- and digest, explain_version) changes; `pendente` marks the rows a run planned and has not reached yet (a new
-- classification gets a placeholder row: pendente, no outcome; an old one keeps its text until it is replaced).

CREATE TABLE IF NOT EXISTS ai.rtc_cclasstrib_explicacao (
    cltr_id                integer     PRIMARY KEY,         -- silver.rtc_cclasstrib.cltr_id
    grupo_tributo          text        NOT NULL,            -- IBSCBS | IS
    cclasstrib             text        NOT NULL,
    outcome                text,                            -- domain: constraint below; NULL = never generated yet
    recusa                 text,                            -- model | no_valid_citation | invalid_json | truncated
    explicacao             text,                            -- what is shown: the explanation, or the fixed text
    resposta_modelo        text,                            -- the model's own text when it is not shown
    fontes                 text[]      NOT NULL DEFAULT '{}',  -- "art. 138, § 2º": the law cited as source
    dispositivos_ponte     text[]      NOT NULL DEFAULT '{}',  -- the provisions the bridge links (the anchors)
    dispositivos_contexto  text[]      NOT NULL DEFAULT '{}',  -- what the context showed (what may be cited)
    dispositivos_citados   text[]      NOT NULL DEFAULT '{}',  -- the valid citations
    citacoes               jsonb       NOT NULL DEFAULT '[]',  -- every citation with its status (valid | outside_context | not_found | foreign)
    cita_ponte             boolean,                         -- a valid citation on a bridge provision (or inside it)
    numeros_sem_fonte      text[]      NOT NULL DEFAULT '{}',  -- percentages stated that neither the table nor the law shown carry
    violacoes              integer     NOT NULL DEFAULT 0,  -- citations dropped (outside the context, not found)
    ancora_parcial         boolean     NOT NULL DEFAULT false, -- part of the reference is ambiguous / not found
    context_tokens         integer,                         -- the retriever's estimate (words x 1.7)
    prompt_eval_count      integer,                         -- as Ollama reported (a cached prefix counts less)
    eval_count             integer,
    latency_s              numeric(8,2),
    pendente               boolean     NOT NULL DEFAULT false,
    row_fingerprint        text        NOT NULL,
    model                  text,                            -- NULL for no_anchor (no LLM call)
    model_digest           text,
    prompt_version         text,
    explain_version        text        NOT NULL,
    rtc_sha                text        NOT NULL,            -- lineage: reference, law and bridge in use
    law_sha256             text        NOT NULL,
    bridge_version         text        NOT NULL,
    generated_at           timestamptz NOT NULL DEFAULT now()
);
ALTER TABLE ai.rtc_cclasstrib_explicacao DROP CONSTRAINT IF EXISTS ck_rtc_cclasstrib_explicacao_outcome;
ALTER TABLE ai.rtc_cclasstrib_explicacao ADD CONSTRAINT ck_rtc_cclasstrib_explicacao_outcome
    CHECK (outcome IN ('explained', 'refused', 'no_anchor', 'invalid_json', 'truncated'));
CREATE INDEX IF NOT EXISTS ix_rtc_cclasstrib_explicacao_code ON ai.rtc_cclasstrib_explicacao (cclasstrib, grupo_tributo);

COMMENT ON TABLE ai.rtc_cclasstrib_explicacao IS
    'Cited explanation of each official cClassTrib from the LC 214 provisions the bridge links (ADR 0022, rtc04_explain).';
